[CmdletBinding()]
param([string]$ProjectRoot=(Get-Location).Path,[string]$TraceabilityPath='',[switch]$RequireTraceability)
$ErrorActionPreference='Stop'; if ($TraceabilityPath) { throw 'TraceabilityPath is unsupported. Use ProjectRoot with .spec/traceability.yaml.' }; . (Join-Path $PSScriptRoot 'python-runtime.ps1'); $python = Get-TengerPython; if(-not $RequireTraceability){Write-Warning 'Traceability validation always requires .spec/traceability.yaml in the current executable governance contract.'}; & $python (Join-Path $PSScriptRoot 'validate_core.py') trace --project-root $ProjectRoot; exit $LASTEXITCODE
